import{z as i,x as p,o as r,c as A,q as l,j as o,D as E,d as t,s as B,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"业绩持续性","description":"","frontmatter":{"title":"业绩持续性","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/performance-persistence.md","filePath":"quant/performance-persistence.md","lastUpdated":1791063341000}'),h={name:"quant/performance-persistence.md"};function d(m,a,F,c,u,f){const n=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=l('<h1 id="业绩持续性" tabindex="-1">业绩持续性 <a class="header-anchor" href="#业绩持续性" aria-label="Permalink to &quot;业绩持续性&quot;">​</a></h1><div class="epigraph"><p>扣费后，共同基金的业绩持续性大部分被动量与费用解释掉；剩下的「热手」很弱，且会被资金流冲淡。</p><footer>—— Carhart, On Persistence in Mutual Fund Performance, Journal of Finance, 1997；技能与运气见 Fama and French, Journal of Finance, 2010</footer></div><p><a href="/quant/fees-compounding">上一课</a>说明费用确定地吃复利。持续性的缺口是：<strong>扣费后的超额会不会重复</strong>。Carhart 用四因子（市场、规模、价值、动量，见 <a href="/quant/carhart4">Carhart 四因子</a>）表明：一年期的「赢家基金」持续性很大一块是股票动量加上费用差异，不是稳定的选股 alpha。Fama–French（2010）用 bootstrap 问：行业里有多少基金的 alpha 超出运气。Berk–Green 把持续性弱写成均衡：技能会吸引资金直到净 alpha 为零。本课不重做截面定价实证，只把这些结论接到产品评价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投资人选基金就是在做因子择时加选经理。<span class="marginnote">alpha 就是把市场涨跌、规模、价值、动量这些公开因子能解释的部分全部扣掉后，剩下的收益。直觉类比：考试整体难度下调、全班都多考 10 分，你只有超出这 10 分的部分才算真本事——基金超出「大盘解释力」的那一小块，才是它的 alpha。</span>若持续性只来自未扣的动量暴露，买「去年前十分位」等于买拥挤动量。问题是分层：毛 alpha、净 alpha、暴露调整后的残差。Kosowski、Timmermann、Wermers、White 的 bootstrap 显示右尾可能有技能，但可投资性还要过容量与后课资金流。对冲基金样本有存活偏差与回填，持续性更容易被高估。</p><p>与生命周期：策略衰减是信号层；基金持续性是产品层。一只基金可以换信号继续活，持续性仍可以断。</p><h3 id="运气的零假设要含费用" tabindex="-1">运气的零假设要含费用 <a class="header-anchor" href="#运气的零假设要含费用" aria-label="Permalink to &quot;运气的零假设要含费用&quot;">​</a></h3><p>把净收益对因子回归得到 \\(\\hat\\alpha\\)，再问是否大于零。零假设若不管费用，平庸经理也会因为费率为正而 \\(\\alpha\\lt 0\\)。Fama–French 的「技能」是相对净 alpha 的横截面：真正的问题是右尾是否厚过运气。不要用单只三年夏普宣称技能，见后课抽样误差。</p><p><span class="marginnote">排序期与持有期若重叠，或用同一段动量因子两边解释，会制造假持续性。Carhart 的贡献之一就是把动量从「经理技能」里拿出来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>排序：过去 1 年净收益或净 alpha → 随后持有期。控制：四因子暴露、费用份额、规模。稳健：发表后子样本、存活偏差处理。对冲基金：用报告频率与锁定期对齐，不可用月频平滑当低波动技能。</p><p><span class="marginnote">bootstrap（自助法）就是用电脑反复「重抽再算」来度量随机性：像把全班的分数放回袋子里重抽一万次，看纯靠运气能造出多大的「好成绩」。它不假设收益服从什么分布，只用数据本身回答「右尾里有多少是运气造不出来的」。</span></p>',12)),(r(),o(s,null,{default:E(()=>[B(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%A0%B7%E6%9C%AC%EF%BC%9A%E5%85%A8%E9%83%A8%E5%9F%BA%E9%87%91%E7%9A%84%E5%8E%86%E5%8F%B2%E5%87%80%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20B%5B%22bootstrap%20%E9%87%8D%E6%8A%BD%E6%A0%B7%E6%9E%84%E9%80%A0%E8%BF%90%E6%B0%94%E5%9F%BA%E5%87%86%22%5D%0A%20%20B%20--%3E%20N%5B%22%E7%BA%AF%E8%BF%90%E6%B0%94%E8%83%BD%E7%94%9F%E6%88%90%E7%9A%84%20alpha%20%E5%88%86%E5%B8%83%22%5D%0A%20%20R%5B%22%E7%9C%9F%E5%AE%9E%E5%90%84%E5%9F%BA%E9%87%91%E7%9A%84%E5%87%80%20alpha%22%5D%20--%3E%20C%5B%22%E7%9C%9F%E5%AE%9E%E5%8F%B3%E5%B0%BE%E4%B8%8E%E8%BF%90%E6%B0%94%E5%88%86%E5%B8%83%E6%AF%94%E8%BE%83%22%5D%0A%20%20C%20--%3E%20M%5B%22%E5%A4%9A%E6%95%B0%E5%9F%BA%E9%87%91%E4%B8%8E%E8%BF%90%E6%B0%94%E6%97%A0%E5%BC%82%22%5D%0A%20%20C%20--%3E%20S%5B%22%E5%B0%91%E6%95%B0%E5%9F%BA%E9%87%91%E5%8F%B3%E5%B0%BE%E8%B6%85%E5%87%BA%E8%BF%90%E6%B0%94%22%5D%0A%20%20S%20--%3E%20V%5B%22%E5%8F%AF%E6%8A%95%E8%B5%84%E6%80%A7%EF%BC%9A%E5%AE%B9%E9%87%8F%E3%80%81%E8%B4%B9%E7%94%A8%E3%80%81%E8%B5%84%E9%87%91%E6%B5%81%E5%86%8D%E6%A3%80%E9%AA%8C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"若技能存在且资金有限，净 alpha 可暂为正。资金追逐（下课）把 AUM 推到技能的容量上限，净 alpha 被摊薄到零（Berk–Green）。费用提高摊薄速度。动量使短期排序看起来像技能。于是可投资的持续性短、弱、容量小。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为 Berk–Green 说「好基金业绩会一直差」。它说的是技能吸引资金、资金把规模推到容量上限、新钱把 alpha 摊薄到零——基金对投资人不再有超额，但经理照旧收管理费。这不是经理变笨，而是均衡结果。")],-1)),(r(),o(s,null,{default:E(()=>[B(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Past%5B%22%E8%BF%87%E5%8E%BB%E5%87%80%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20Mom%5B%22%E8%82%A1%E7%A5%A8%E5%8A%A8%E9%87%8F%22%5D%0A%20%20Past%20--%3E%20Fee%5B%22%E8%B4%B9%E7%94%A8%E5%B7%AE%E5%BC%82%22%5D%0A%20%20Past%20--%3E%20Skill%5B%22%E6%AE%8B%E5%B7%AE%E6%8A%80%E8%83%BD%22%5D%0A%20%20Skill%20--%3E%20Flow%5B%22%E8%B5%84%E9%87%91%E6%B5%81%E5%85%A5%E6%91%8A%E8%96%84%22%5D%0A%20%20Mom%20--%3E%20Weak%5B%22%E5%8F%AF%E6%8A%95%E8%B5%84%E6%8C%81%E7%BB%AD%E6%80%A7%E5%BC%B1%22%5D%0A%20%20Flow%20--%3E%20Weak%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给「如何选到未来前十分位」的清单。私募与封闭结构改变流量机制，结论不能直接搬。下一课专门写流。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扣费后共同基金持续性大部分是动量与费用，不是稳定 alpha。</li><li>技能若存在，会被资金流摊薄（Berk–Green）。</li><li>单只短样本夏普不够当技能证据。</li><li>出处：Carhart, <em>JF</em>, 1997；Fama and French, <em>JF</em>, 2010；Berk and Green, <em>JPE</em>, 2004。</li></ul>',4))])}const _=i(h,[["render",d]]);export{C as __pageData,_ as default};
